"""Publish native evidence for the installed punch-card loom and linked layer view."""
from pathlib import Path
import hashlib
import html
import json
import shutil

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'doc/book/iterations/2026-10-10-jacquard-cards-and-layers'


def main():
    runtime = json.loads((OUT/'tests.json').read_text())
    museum = json.loads((OUT/'museum-tests.json').read_text())
    assert runtime['passed'] and museum['passed']
    assert all(c['passed'] for result in [runtime, museum] for c in result['checks'])
    source = OUT/'source'
    source.mkdir(exist_ok=True)
    for p in (ROOT/'commons/artifacts/jacquard_weaver').iterdir():
        if p.suffix in {'.gd', '.gdshader', '.tscn', '.md'}:
            shutil.copy2(p, source/p.name)
    for name in ['jacquard_weaver_test.gd', 'jacquard_museum_test.gd']:
        shutil.copy2(ROOT/'tools/probes'/name, source/name)
    shutil.copy2(ROOT/'commons/artifacts/registry/jacquard_weaver.json', source/'registry.json')
    hashes = {p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in source.iterdir() if p.is_file()}
    (OUT/'source-hashes.json').write_text(json.dumps(hashes,indent=2)+'\n',encoding='utf-8')
    style='''*{box-sizing:border-box}body{margin:0;background:#f1eee6;color:#29262a;font:18px/1.55 Georgia,serif}main{max-width:1300px;margin:auto;padding:32px 28px 80px}nav,.eyebrow,figcaption,.meta{font:14px/1.5 system-ui,sans-serif}nav{display:flex;flex-wrap:wrap;gap:22px;border-bottom:1px solid #c8beb7;padding-bottom:20px}a{color:#8d3457;text-underline-offset:4px}h1{font:clamp(45px,7vw,90px)/1 Georgia,serif;letter-spacing:-.035em;margin:25px 0}h2{font:34px/1.15 Georgia,serif;margin:40px 0 16px}.lead{font-size:25px;max-width:800px}.eyebrow{margin-top:35px;letter-spacing:.12em;text-transform:uppercase}figure{margin:26px 0}img{width:100%;display:block;background:#22282c}figcaption{padding-top:10px;color:#60585b}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.pair figure{margin:0}.rule{font:20px/1.5 system-ui,sans-serif;border-top:1px solid #c8beb7;border-bottom:1px solid #c8beb7;padding:20px 0;margin:32px 0}.copy{max-width:850px}li{margin-bottom:13px}.receipt{background:#e2e7dd;padding:22px 28px}.meta{color:#635c60}code{font:14px/1.5 monospace}details{padding:18px 0;border-top:1px solid #c8beb7}summary{cursor:pointer;font-family:system-ui,sans-serif}@media(max-width:750px){main{padding:24px 18px 60px}.pair{grid-template-columns:1fr}.lead{font-size:22px}}'''
    def figure(name, caption):
        assert (OUT/(name+'.png')).exists()
        return f'<figure><a href="{name}.png"><img loading="lazy" src="{name}.png" alt="{html.escape(caption)}"></a><figcaption>{caption}</figcaption></figure>'
    body='''<nav><a href="../2026-10-10-shader-pattern-survey/gallery.html">Pattern and shader gallery</a><a href="#use">Try the machine</a><a href="#layers">The 3D layers</a><a href="#evidence">Tests and source</a></nav>
<p class="eyebrow">Endless Museum · Tiling / Symmetry Seventeen · 10 October 2026</p>
<h1>Cards become cloth.</h1>
<p class="lead">Pick up a card. Change its holes. Choose the thread colours. Watch those choices become a crossing—and remain in the cloth after you change your mind.</p>
<div class="rule">Punched card → raised warp → shuttle pass → woven record → 3D layers</div>'''
    body=body.replace('<a href="#use">','<a href="#tartan">Make tartan</a><a href="#use">')
    body+='''<div class="copy"><h2 id="tartan">Tartan: two colour sequences, one weave</h2><p>Press <b>TARTAN + CLEAR</b>, then <b>WEAVE 96 PICKS</b> on the layer table. Use ONE PICK or RUN to watch individual passes. The loom repeats the twelve-hook pattern eight times across <b>96 warp threads</b> and weaves 96 actual rows. The sample is roughly <b>2.4 metres square</b>, with closely packed, flattened yarns and a matte surface. Its colours repeat in both directions over a two-over, two-under twill. The shifting crossings make diagonal lines; the matching colour stripes make the check. This is an authored teaching sample, not a named or registered tartan.</p></div>'''
    body+=figure('tartan-museum','The coloured loom and linked layer sculpture in Symmetry Seventeen. Native Godot capture from the actual museum, with 96 recorded picks.')
    body+='''<div class="copy"><ol><li><b>WARP COLOURS:</b> press any of the twelve swatches to cycle its yarn colour. This edits a proposed threading. <b>THREAD + CLEAR</b> applies it and starts a fresh cloth in both views.</li><li><b>WEFT COLOURS:</b> edit the twelve-colour repeat for future shuttle passes. The small mint marker identifies the colour being used. The running pass and previously woven rows retain their recorded colours.</li><li><b>MATCH WEFT</b> copies the proposed warp colour repeat into the weft sequence. Each direction remains independently editable afterward.</li><li>Keep the colours and change <b>TWILL</b> to <b>PLAIN</b>. Watch the same stripes produce different crossings. Or keep the cards and change the weft colours: the structure stays while the next rows change.</li></ol><p>The swatches cycle through red, navy, green, cream, gold, black, pink and grey. The eight-card chain and twelve-colour repeat advance independently.</p></div>'''
    body+=figure('tartan-controls','Two rows of physical colour buttons: proposed warp threading above, future weft sequence below. Rethreading is explicitly labelled THREAD + CLEAR.')
    body+='<div class="pair">'+figure('tartan-flat','Dense cloth: 96 warp threads × 96 recorded picks. These are interlaced yarn meshes; the flat diagram is hidden when closed.')+figure('tartan-layers','The same tartan opened through height. Yarns become narrower for inspection and their over/under separation is enlarged. The flat drawdown remains below.')+'</div>'
    body+=figure('tartan-detail','Close view of the actual flattened yarns and their 2/2 twill crossings. Subtle filament shading adds surface detail; geometry carries the weave.')
    body+='''<div class="copy"><p>A tartan sett specifies the order and number of coloured threads. This small study uses matching repeats in warp and weft; see the Scottish Register of Tartans’ <a href="https://www.tartanregister.gov.uk/threadcount">threadcount guidance</a>. Colour and lift are separate data: a punched hole raises a thread of whichever colour was threaded there.</p></div>'''
    body+='''<div class="copy"><h2 id="use">A program you can pick up</h2><ol>
<li>Start with <b>PLAIN</b>, <b>TWILL</b> or <b>DIAMOND</b>. Each of the eight cards controls one pass; four spare cards wait on the rack.</li>
<li><b>Grab and release cards into empty numbered slots.</b> Change their order, remove one or add a spare. Empty slots are skipped. Removing all cards stops new passes.</li>
<li>Press <b>ONE PICK</b> to follow one cycle, or <b>RUN / STOP</b> to repeat the chain. Watch the enlarged card, the lifted hooks and the shuttle.</li>
<li>Picking up a card selects it for editing. Use the twelve hook buttons to punch or patch it; <b>NEXT CARD</b> also changes the selection. <b>A hole lifts its warp thread.</b> It does not specify a colour.</li>
<li>Change the next card while weaving. The current pass keeps the mask it already read; the finished cloth keeps every earlier choice.</li></ol></div>'''
    body+='<div class="pair">'+figure('loom','The twelve-hook machine. Raised and lowered cream warp threads open a shed for the pink shuttle.')+figure('cards','Real holes in pickable cards, arranged in eight numbered sockets. Release near an empty slot to install a card.')+'</div>'
    body+='''<div class="copy"><h2 id="layers">Open the pattern into space</h2><p>The companion sculpture receives the <b>same committed records</b> as the loom, including yarn colours. Pull its pink handle to open successive picks vertically. The shader transforms the same mesh throughout, keeping interaction responsive as the cloth becomes denser. The threads retain their over/under relationships, and the flat diagram beneath shows the upper thread at each crossing.</p><p><b>FLAT</b> returns the sample to a surface; <b>LAYERS</b> opens it upward. Consecutive picks of the same colour form a continuous weft path; a colour change starts another yarn at the edge. Knots and loose tails are not modeled.</p></div>'''
    body+='<div class="pair">'+figure('flat','The recorded sample laid flat. The first eight picks use plain weave; the next sixteen use the diamond card set.')+figure('layers','The same sample unfolded through height. Each pink pass is one recorded card decision; changing the spacing preserves every crossing bit.')+'</div>'
    body+='''<div class="copy"><h2>Where it belongs</h2><p><b>Tiling → Symmetry Seventeen, cell [16,14].</b> It sits near the existing pattern machines. The hand loom remains at [16,21]. This makes a concrete continuation: a hand chooses a lift, a card keeps that choice, a chain repeats it, and the cloth records the consequences.</p><p>The machine starts with bare warp and a twill card set. <b>CLEAR CLOTH</b> clears both views while keeping the cards. The sample stops at 128 picks. WEAVE 96 PICKS adds real card cycles and preserves earlier rows; each twelve-hook lift repeats eight times across the width. These objects currently retain their state for the loaded session.</p><h2>What this model shows</h2><p>It is a simplified Jacquard selection mechanism: holes select hooks that raise warp threads. Historical card sets could store another pattern for a loom. See the Science Museum Group’s <a href="https://collection.sciencemuseumgroup.org.uk/objects/co8404795/ribbon-loom-with-jacquard-head">ribbon loom with Jacquard head</a> and <a href="https://collection.sciencemuseumgroup.org.uk/objects/co471243/jacquard-cards">Jacquard cards</a>.</p><p>The card cylinder and mechanical linkages are abstracted. Thread crossings are geometric; yarn tension, friction and cloth deformation are not simulated. The layered sculpture is an expanded view of the record, not a claim that this loom manufactures a multilayer textile. The default cream warp and pink weft help distinguish the two directions. The tartan controls add separate colour sequences; the flat drawdown displays the upper thread rather than calculating an averaged colour.</p></div>'''
    body+=figure('player-view','The installed loom from a standing working position. Buttons use the museum’s existing interaction system; cards use XR Tools pickup and desktop grab/drop.')
    body+=f'''<div class="copy"><h2 id="evidence">Run in the actual project</h2><div class="receipt"><b>{len(runtime['checks'])} runtime assertions + {len(museum['checks'])} museum checks passed.</b><p>Card insertion, reordering, rejection of occupied slots, immutable in-flight masks, retained history, crossing order, bounded geometry, XR pickup/release, slider movement, colour-button signals, independent card/colour repeats and faithful coloured drawdowns, batch weaving, dense crossings and GPU opening without mesh replacement were exercised. The actual hall loaded both the new studio and the existing hand loom; three standing positions were checked for obstructions.</p><p>XR tests use simulated controllers. Physical headset reach and comfort still need your playthrough.</p></div><p class="meta"><a href="tests.json">Runtime checks</a> · <a href="museum-tests.json">Museum checks</a> · <a href="runtime-log.txt">Runtime log</a> · <a href="museum-log.txt">Museum log</a></p><details><summary>Source and implementation notes</summary><p><a href="source/README.md">Artifact guide</a> · <a href="source/weave_program.gd">Card program and history</a> · <a href="source/jacquard_weaver.gd">Loom</a> · <a href="source/weave_layers.gd">Layer view</a> · <a href="source/punch_card.gd">Pickable card</a> · <a href="source/yarn_colours.gd">Yarn palette and sett</a> · <a href="source/weave_fabric.gd">Dense fabric geometry</a> · <a href="source/woven_yarn.gdshader">Opening and yarn shader</a> · <a href="source-hashes.json">Source hashes</a></p><p>Tokens: <code>jacquard_studio</code> (the installed pair), <code>jacquard_weaver</code>, <code>weave_layers</code>. The separate layer scene waits for a supplied record.</p><p>The probes encountered existing project startup warnings about unrelated audio resources, Jolt solver bias and registry metadata. They completed successfully. No tutorial or reflective book text was rewritten for this artifact build.</p></details></div>'''
    (OUT/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cards become cloth · Endless Museum</title><style>{style}</style></head><body><main>{body}</main></body></html>',encoding='utf-8')
    print('Published',OUT/'index.html')


if __name__ == '__main__':
    main()
